CustomField.formula:
/* Calculate the number of business days since CreatedDate */
IF(
  BEGINS(OwnerId, "00G"), /* Check if owner is a Queue (Queue IDs start with "00G") */
  5 * FLOOR((TODAY() - DATEVALUE(CreatedDate)) / 7) +
  MIN(5,
    MAX(0,
      MOD(TODAY() - DATEVALUE(CreatedDate), 7) -
      IF(
        MOD(DATEVALUE(CreatedDate) - DATE(1900, 1, 7), 7) = 6, 1, /* Saturday → Subtract 1 */
        IF(
          MOD(DATEVALUE(CreatedDate) - DATE(1900, 1, 7), 7) = 0, 2, 0 /* Sunday → Subtract 2 */
        )
      )
    )
  ),
  0 /* If owner is NOT a queue, return 0 */
)
